Rule.Source:
import sailpoint.object.Filter;
  import sailpoint.object.ProvisioningPlan.AccountRequest;
  import sailpoint.object.ProvisioningPlan.AttributeRequest;
  import sailpoint.connector.Connector;
  import sailpoint.connector.ConnectorFactory;
  import sailpoint.connector.ObjectNotFoundException;

  if (plan == null || plan.getAccountRequests() == null) return;

  for (Object o : plan.getAccountRequests()) {
      AccountRequest acctReq = (AccountRequest) o;
      if (!"ActiveDirectory".equals(acctReq.getApplicationName())
              || !AccountRequest.Operation.Create.equals(acctReq.getOperation())) {
          continue;
      }

      AttributeRequest dnReq = acctReq.getAttributeRequest("distinguishedName");
      if (dnReq == null || dnReq.getValue() == null) continue;

      AttributeRequest samReq = acctReq.getAttributeRequest("sAMAccountName");
      String baseSam = (samReq != null) ? (String) samReq.getValue() : null;

      String candidateDn = (String) dnReq.getValue();
      String rdn = candidateDn.substring(3, candidateDn.indexOf(","));
      String parentDn = candidateDn.substring(candidateDn.indexOf(",") + 1);
      String candidateSam = baseSam;

      Connector connector = ConnectorFactory.getConnector(application, null);
      int suffix = 1;

      while (true) {
          boolean dnExists = true;
           try {
                connector.getObject("account", candidateDn, null);
            } catch (ObjectNotFoundException e) {
                dnExists = false;
            } catch (Exception e) {
                log.error("DN uniqueness check failed for " + candidateDn + ": " + e.getMessage());
                dnExists = false;   // decide: fail-open (proceed) vs. rethrow (abort)
            }

          boolean samExists = false;
          if (candidateSam != null) {
              Object it = null;
              try {
                  it = connector.iterateObjects("account", Filter.eq("sAMAccountName", candidateSam), null);
                  samExists = (it != null && it.hasNext());
              } catch (Exception e) {
                  log.error("Failed checking sAMAccountName uniqueness: " + e.getMessage());
              } finally {
                  if (it != null) it.close();
              }
          }

          if (!dnExists && !samExists) break;

          suffix++;
          candidateDn = "CN=" + rdn + " " + suffix + "," + parentDn;
          if (baseSam != null) {
              String suffixedSam = baseSam + suffix;
              candidateSam = suffixedSam.length() > 20 ? suffixedSam.substring(0, 20) : suffixedSam;
          }
      }

      dnReq.setValue(candidateDn);
      acctReq.setNativeIdentity(candidateDn);
      if (samReq != null && candidateSam != null) {
          samReq.setValue(candidateSam);
      }
  }
